nc -->\n\t\t<div class=\"settings-section__field\">\n\t\t\t<label>{{ t('sendentsynchroniser', 'Enable IMAP Setup push') }}</label>\n\t\t\t<div class=\"settings-section__input-row\">\n\t\t\t\t<select v-model=\"imapSyncEnabled\"\n\t\t\t\t\tclass=\"settings-section__input\"\n\t\t\t\t\t:disabled=\"!mailAppInstalled\"\n\t\t\t\t\t@change=\"saveIMAPSync\">\n\t\t\t\t\t<option value=\"true\">\n\t\t\t\t\t\t{{ t('sendentsynchroniser', 'Enabled') }}\n\t\t\t\t\t</option>\n\t\t\t\t\t<option value=\"false\">\n\t\t\t\t\t\t{{ t('sendentsynchroniser', 'Disabled') }}\n\t\t\t\t\t</option>\n\t\t\t\t</select>\n\t\t\t\t<span v-if=\"!mailAppInstalled\" class=\"settings-section__warning\">\n\t\t\t\t\t{{ t('sendentsynchroniser', \"You don't have the mail app installed\") }}\n\t\t\t\t</span>\n\t\t\t\t<span v-if=\"saved.imapSync\" class=\"settings-section__saved\">&#x2713;</span>\n\t\t\t</div>\n\t\t</div>\n\n\t\t<!-- Email domain — used to match a user's Nextcloud email address to the Exchange domain -->\n\t\t<div class=\"settings-section__field\">\n\t\t\t<label>{{ t('sendentsynchroniser', 'Email domain') }}</label>\n\t\t\t<div class=\"settings-section__input-row\">\n\t\t\t\t<input v-model=\"emailDomain\"\n\t\t\t\t\tclass=\"settings-section__input\"\n\t\t\t\t\tplaceholder=\"acme.com\"\n\t\t\t\t\t@keyup=\"debounceSaveEmailDomain\">\n\t\t\t\t<span v-if=\"saved.emailDomain\" class=\"settings-section__saved\">&#x2713;</span>\n\t\t\t</div>\n\t\t</div>\n\n\t\t<!-- Default collections — hidden until feature is ready -->\n\t\t<div class=\"settings-section__hidden\">\n\t\t\t<h3>{{ t('sendentsynchroniser', 'Default collections') }}</h3>\n\t\t\t<p class=\"settings-section__subtitle\">\n\t\t\t\t{{ t('sendentsynchroniser', 'When set, these collections are automatically created for users during activation. Leave empty to use Nextcloud defaults (Personal / Contacts).') }}\n\t\t\t</p>\n\n\t\t\t<!-- Default calendar -->\n\t\t\t<div class=\"settings-section__field\">\n\t\t\t\t<label>{{ t('sendentsynchroniser', 'Default calendar URI') }}</label>\n\t\t\t\t<div class=\"settings-section__input-row\">\n\t\t\t\t\t<input v-model=\"defaultCalendar\"\n\t\t\t\t\t\tclass=\"settings-section__input\"\n\t\t\t\t\t\tplaceholder=\"e.g. exchange\"\n\t\t\t\t\t\t@keyup=\"debounceSaveDefaultCalendar\">\n\t\t\t\t\t<span v-if=\"saved.defaultCalendar\" class=\"settings-section__saved\">&#x2713;</span>\n\t\t\t\t</div>\n\t\t\t</div>\n\n\t\t\t<!-- Default addressbook -->\n\t\t\t<div class=\"settings-section__field\">\n\t\t\t\t<label>{{ t('sendentsynchroniser', 'Default addressbook URI') }}</label>\n\t\t\t\t<div class=\"settings-section__input-row\">\n\t\t\t\t\t<input v-model=\"defaultAddressbook\"\n\t\t\t\t\t\tclass=\"settings-section__input\"\n\t\t\t\t\t\tplaceholder=\"e.g. exchange-contacts\"\n\t\t\t\t\t\t@keyup=\"debounceSaveDefaultAddressbook\">\n\t\t\t\t\t<span v-if=\"saved.defaultAddressbook\" class=\"settings-section__saved\">&#x2713;</span>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t</div>\n\n\t\t<h3>{{ t('sendentsynchroniser', 'Enrollment reminders') }}</h3>\n\n\t\t<!-- Reminder type -->\n\t\t<div class=\"settings-section__field\">\n\t\t\t<label>{{ t('sendentsynchroniser', 'Reminder type') }}</label>\n\t\t\t<div class=\"settings-section__input-row\">\n\t\t\t\t<select v-model=\"reminderType\"\n\t\t\t\t\tclass=\"settings-section__input\"\n\t\t\t\t\t@change=\"saveReminderType\">\n\t\t\t\t\t<option value=\"1\">\n\t\t\t\t\t\tModal dialog\n\t\t\t\t\t</option>\n\t\t\t\t\t<option value=\"2\" :disabled=\"!notificationsAppInstalled\">\n\t\t\t\t\t\tStandard notifications\n\t\t\t\t\t</option>\n\t\t\t\t\t<option value=\"3\" :disabled=\"!notificationsAppInstalled\">\n\t\t\t\t\t\tModal dialog and standard notifications\n\t\t\t\t\t</option>\n\t\t\t\t</select>\n\t\t\t\t<span v-if=\"!notificationsAppInstalled\" class=\"settings-section__warning\">\n\t\t\t\t\t{{ t('sendentsynchroniser', \"You don't have the notifications app installed\") }}\n\t\t\t\t</span>\n\t\t\t\t<span v-if=\"saved.reminderType\" class=\"settings-section__saved\">&#x2713;</span>\n\t\t\t</div>\n\t\t</div>\n\n\t\t<!-- Notification method -->\n\t\t<div class=\"settings-section__field\">\n\t\t\t<label>{{ t('sendentsynchroniser', 'Applications to show modal dialog on') }}</label>\n\t\t\t<div class=\"settings-section__input-row\">\n\t\t\t\t<select v-model=\"notificationMethod\"\n\t\t\t\t\tclass=\"settings-section__input\"\n\t\t\t\t\t@change=\"saveNotificationMethod\">\n\t\t\t\t\t<option value=\"1\">\n\t\t\t\t\t\tShow in Mail, Calendar, Contacts, and Tasks\n\t\t\t\t\t</option>\n\t\t\t\t\t<option value=\"2\">\n\t\t\t\t\t\tShow in Files\n\t\t\t\t\t</option>\n\t\t\t\t\t<option value=\"3\">\n\t\t\t\t\t\tShow everywhere (options 1 and 2 combined)\n\t\t\t\t\t</option>\n\t\t\t\t</select>\n\t\t\t\t<span v-if=\"saved.notificationMethod\" class=\"settings-section__saved\">&#x2713;</span>\n\t\t\t</div>\n\t\t</div>\n\n\t\t<!-- Notification interval -->\n\t\t<div class=\"settings-section__field\">\n\t\t\t<label>{{ t('sendentsynchroniser', 'Notifications interval in days') }}</label>\n\t\t\t<div class=\"settings-section__input-row\">\n\t\t\t\t<input v-model=\"notificationInterval\"\n\t\t\t\t\tclass=\"settings-section__input\"\n\t\t\t\t\t:disabled=\"!notificationsAppInstalled\"\n\t\t\t\t\t@change=\"saveNotificationInterval\">\n\t\t\t\t<span v-if=\"!notificationsAppInstalled\" class=\"settings-section__warning\">\n\t\t\t\t\t{{ t('sendentsynchroniser', \"You don't have the notifications app installed\") }}\n\t\t\t\t</span>\n\t\t\t\t<span v-if=\"saved.notificationInterval\" class=\"settings-section__saved\">&#x2713;</span>\n\t\t\t</div>\n\t\t</div>\n\n\t\t<h3>{{ t('sendentsynchroniser', 'Meeting invitations') }}</h3>\n\n\t\t<!-- iMIP/iTip suppression. Stored value graphApiMode: 'true' = suppression ON\n\t\t\t (Nextcloud silent, Exchange/Graph sole sender). Default ON. -->\n\t\t<div class=\"settings-section__field\">\n\t\t\t<label>{{ t('sendentsynchroniser', 'Disable Nextcloud meeting invitations') }}</label>\n\t\t\t<div class=\"settings-section__input-row\">\n\t\t\t\t<select v-model=\"graphApiMode\"\n\t\t\t\t\tclass=\"settings-section__input\"\n\t\t\t\t\t@change=\"onGraphApiModeChange\">\n\t\t\t\t\t<option value=\"true\">\n\t\t\t\t\t\t{{ t('sendentsynchroniser', 'Enabled') }}\n\t\t\t\t\t</option>\n\t\t\t\t\t<option value=\"false\">\n\t\t\t\t\t\t{{ t('sendentsynchroniser', 'Disabled') }}\n\t\t\t\t\t</option>\n\t\t\t\t</select>\n\t\t\t\t<span v-if=\"saved.graphApiMode\" class=\"settings-section__saved\">&#x2713;</span>\n\t\t\t</div>\n\t\t\t<p class=\"settings-section__hint\">\n\t\t\t\t{{ graphApiMode === 'true'\n\t\t\t\t\t? t('sendentsynchroniser', 'Nextcloud will not send meeting invitations. Exchange is the sole sender, which prevents attendees from receiving duplicate invitations.')\n\t\t\t\t\t: t('sendentsynchroniser', 'Nextcloud sends its own meeting invitations. Attendees may receive duplicate invitations.') }}\n\t\t\t</p>\n\t\t</div>\n\n\t\t<!-- Consequences gate — only shown when disabling suppression -->\n\t\t<div v-if=\"showSuppressionWarning\"\n\t\t\tclass=\"suppression-modal__overlay\"\n\t\t\t@click.self=\"cancelDisableSuppression\">\n\t\t\t<div class=\"suppression-modal__content\">\n\t\t\t\t<div class=\"suppression-modal__header\">\n\t\t\t\t\t<h2>{{ t('sendentsynchroniser', 'Let Nextcloud send invitations again?') }}</h2>\n\t\t\t\t</div>\n\t\t\t\t<div class=\"suppression-modal__body\">\n\t\t\t\t\t<p>{{ t('sendentsynchroniser', 'Nextcloud will start sending its own meeting invitations again. Attendees may receive duplicate invitations — one from Nextcloud and one from Exchange.') }}</p>\n\t\t\t\t</div>\n\t\t\t\t<div class=\"suppression-modal__footer\">\n\t\t\t\t\t<button class=\"button\" @click=\"cancelDisableSuppression\">\n\t\t\t\t\t\t{{ t('sendentsynchroniser', 'Cancel') }}\n\t\t\t\t\t</button>\n\t\t\t\t\t<button class=\"button suppression-modal__confirm\" @click=\"confirmDisableSuppression\">\n\t\t\t\t\t\t{{ t('sendentsynchroniser', 'Enable Nextcloud invitations') }}\n\t\t\t\t\t</button>\n\t\t\t\t</div>\n\t\t\t</div>\n\t\t</div>\n\t</div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, reactive } from 'vue'\nimport { translate as t } from '@nextcloud/l10n'\nimport { generateUrl, imagePath } from '@nextcloud/router'\nimport axios from '@nextcloud/axios'\n\nconst props = defineProps<{\n\tinitialSharedSecret: string\n\tinitialImapSyncEnabled: boolean\n\tinitialEmailDomain: string\n\tinitialReminderType: string | number\n\tinitialNotificationMethod: string | number\n\tinitialNotificationInterval: string | number\n\tinitialDefaultCalendar: string\n\tinitialDefaultAddressbook: string\n\tinitialGraphApiMode: string\n\tmailAppInstalled: boolean\n\tnotificationsAppInstalled: boolean\n}>()\n\nconst sharedSecret = ref(props.initialSharedSecret)\nconst imapSyncEnabled = ref(props.initialImapSyncEnabled ? 'true' : 'false')\nconst emailDomain = ref(props.initialEmailDomain)\nconst reminderType = ref(String(props.initialReminderType))\nconst notificationMethod = ref(String(props.initialNotificationMethod))\nconst notificationInterval = ref(String(props.initialNotificationInterval))\nconst defaultCalendar = ref(props.initialDefaultCalendar)\nconst defaultAddressbook = ref(props.initialDefaultAddressbook)\nconst graphApiMode = ref(props.initialGraphApiMode === 'false' ? 'false' : 'true')\nconst showSuppressionWarning = ref(false)\nconst showSecret = ref(false)\nconst viewIconUrl = imagePath('sendentsynchroniser', 'view.svg')\n\nconst saved = reactive<Record<string, boolean>>({})\n\n/**\n *\n * @param key\n */\nfunction showSaved(key: string) {\n\tsaved[key] = true\n\tsetTimeout(() => { saved[key] = false }, 1500)\n}\n\n/**\n *\n * @param endpoint\n * @param data\n * @param feedbackKey\n */\nasync function saveSetting(endpoint: string, data: Record<string, string>, feedbackKey: string) {\n\tconst url = generateUrl('/apps/sendentsynchroniser/api/1.0/settings/' + endpoint)\n\ttry {\n\t\tawait axios.post(url, data)\n\t\tshowSaved(feedbackKey)\n\t} ca